<?php
/**
 * Title: Contact
 * Slug: wp-ja-restaurant/contact-form
 * Description: The Contact page body of the JA Restaurant source: the Contact Form (name and email side by side, subject, message, copy-to-yourself box that is switched off, Send Email) beside the reservation note, the picture and the address card. The form posts to a theme handler that mails the business's own address (`tracy_contact_to`) only.
 * Categories: wp-ja-restaurant, tracy
 * Post Types: page
 * Inserter: yes
 * Keywords: contact, form, email
 *
 * @package wp-ja-restaurant
 */

$jm_notice = function_exists( 'wp_ja_restaurant_form_notice' ) ? wp_ja_restaurant_form_notice(
	array(
		'ok'           => __( 'Thank you for your message. It has been sent.', 'wp-ja-restaurant' ),
		'error-token'  => __( 'The form expired. Please try again.', 'wp-ja-restaurant' ),
		'error-fields' => __( 'Please fill in every field with an asterisk (*).', 'wp-ja-restaurant' ),
		'error-send'   => __( 'The message could not be sent. Please try again later.', 'wp-ja-restaurant' ),
	)
) : '';
$jr_map = get_posts( array( 'post_type' => 'attachment', 'post_status' => 'inherit', 'name' => 'map-contact', 'posts_per_page' => 1, 'fields' => 'ids' ) );
$jr_map = $jr_map ? (string) wp_get_attachment_url( (int) $jr_map[0] ) : get_theme_file_uri( 'assets/img/placeholder.svg' );
?>
