<div id="t3-mainbody" class="container t3-mainbody"><div class="row"><div id="t3-content" class="jr-content col-xs-12"><?php echo $jm_notice; // phpcs:ignore WordPress.Security.EscapeOutput.OutputNotEscaped -- built and escaped by wp_ja_restaurant_form_notice(). ?><div class="contact"><h1 class="sr-only"><?php esc_html_e( 'Contact Us', 'wp-ja-restaurant' ); ?></h1><div class="row plain-style"><div class="col-md-7 contact-left"><h3><?php esc_html_e( 'Contact Form', 'wp-ja-restaurant' ); ?></h3><div class="contact-form"><form id="contact-form" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>" method="post" class="form-validate form-horizontal"><input type="hidden" name="action" value="jm_contact"><input type="hidden" name="jm_nonce" value="<?php echo esc_attr( wp_create_nonce( 'jm_contact' ) ); ?>"><div aria-hidden="true" style="position:absolute;left:-9999px;width:1px;height:1px;overflow:hidden"><input type="text" name="jform[contact_url]" value="" tabindex="-1" autocomplete="off" aria-label="<?php esc_attr_e( 'Leave this field empty', 'wp-ja-restaurant' ); ?>"></div><fieldset><legend><?php esc_html_e( 'Send an Email. All fields with an asterisk (*) are required.', 'wp-ja-restaurant' ); ?></legend><div class="form-group"><div class="col-md-6 contact-name"><label for="jform_contact_name" class="required control-label"><?php esc_html_e( 'Name', 'wp-ja-restaurant' ); ?><span class="star" aria-hidden="true">&nbsp;*</span></label><input type="text" name="jform[contact_name]" id="jform_contact_name" class="form-control required" size="30" maxlength="60" required autocomplete="name"></div><div class="col-md-6 contact-email"><label for="jform_contact_email" class="required control-label"><?php esc_html_e( 'Email', 'wp-ja-restaurant' ); ?><span class="star" aria-hidden="true">&nbsp;*</span></label><input type="email" inputmode="email" name="jform[contact_email]" id="jform_contact_email" class="form-control required" size="30" maxlength="254" required autocomplete="email"></div></div><div class="form-group"><div class="col-sm-12"><label for="jform_contact_emailmsg" class="required control-label"><?php esc_html_e( 'Subject', 'wp-ja-restaurant' ); ?><span class="star" aria-hidden="true">&nbsp;*</span></label><input type="text" name="jform[contact_subject]" id="jform_contact_emailmsg" class="form-control required" size="60" maxlength="200" required></div></div><div class="form-group contact-mes"><div class="col-sm-12"><label for="jform_contact_message" class="required control-label"><?php esc_html_e( 'Message', 'wp-ja-restaurant' ); ?><span class="star" aria-hidden="true">&nbsp;*</span></label><textarea name="jform[contact_message]" id="jform_contact_message" cols="50" rows="10" maxlength="5000" class="form-control required" required></textarea></div></div><div class="form-group"><div class="col-sm-6"><div class="checkbox"><div class="form-check form-check-inline"><input type="checkbox" id="jform_contact_email_copy" class="form-check-input" disabled></div><label for="jform_contact_email_copy"><?php esc_html_e( 'Send a copy to yourself', 'wp-ja-restaurant' ); ?> <span class="jr-copy-note"><?php esc_html_e( '(not available)', 'wp-ja-restaurant' ); ?></span></label></div></div><div class="col-sm-6 control-btn"><button class="btn btn-primary btn-lg validate" type="submit"><?php esc_html_e( 'Send Email', 'wp-ja-restaurant' ); ?></button></div></div></fieldset></form></div></div><div class="col-md-5 contact-information"><div class="inner"><div class="box-contact box-primary"><h3><?php esc_html_e( 'Contact Us', 'wp-ja-restaurant' ); ?></h3><div class="contact-miscinfo"><dl class="dl-horizontal"><dt><span class="jicons-icons visually-hidden"></span></dt><dd><span class="contact-misc"><?php esc_html_e( 'We take reservations for lunch and dinner.', 'wp-ja-restaurant' ); ?><br/> <?php esc_html_e( 'To make a reservation, please call us at', 'wp-ja-restaurant' ); ?> <a href="tel:+10845550110">(084) 555-0110</a> <?php esc_html_e( 'between 9 am and 5 pm,', 'wp-ja-restaurant' ); ?><br/> <?php esc_html_e( 'Monday to Friday.', 'wp-ja-restaurant' ); ?></span></dd></dl></div></div><div class="contact-image"><img align="middle" src="<?php echo esc_url( $jr_map ); ?>" alt="<?php esc_attr_e( 'Contact image', 'wp-ja-restaurant' ); ?>"></div><div class="box-contact box-white"><h3><?php esc_html_e( 'Contact', 'wp-ja-restaurant' ); ?></h3><dl class="contact-address dl-horizontal"><dt><span class="jicons-icons visually-hidden"></span></dt><dd><span class="contact-street"><i class="fas fa-map-marker-alt"></i><?php esc_html_e( '4 5th Avenue at St. Marks Place, Cathedral District Brooklyn, NY 11217', 'wp-ja-restaurant' ); ?><br/></span></dd><dt><span class="jicons-icons visually-hidden"></span></dt><dd><span class="contact-telephone"><i class="fa fa-phone"></i>(084) 555-0110</span></dd><dt><span class="jicons-icons visually-hidden"></span></dt><dd><span class="contact-mobile"><i class="fa fa-phone-square"></i>048 594 5483</span></dd></dl></div></div></div></div></div></div></div></div>
